            'org.audacityteam.': ['GPL-2.0-or-later'],
            'org.inkscape.': ['GPL-3.0-or-later'],
            'org.freedesktop.': ['MIT'],
        }

    def get_installed_packages(self) -> List[Dict[str, any]]:
        """Get installed Flatpak applications with license information (optimized)."""
        try:
            result = subprocess.run(
                ["flatpak", "list", "--app", "--columns=application,name,version"],
                capture_output=True,
                text=True,
                check=True
            )

            # Parse package list
            app_list = []
            for line in result.stdout.strip().split('\n')[1:]:  # Skip header
                if line.strip():
                    parts = line.split('\t')
                    if len(parts) >= 2:
                        app_id = parts[0]
                        display_name = parts[1] if len(parts) > 1 else app_id
                        version = parts[2] if len(parts) > 2 else "unknown"
                        app_list.append((app_id, display_name, version))

            # Get licenses for all apps concurrently
            packages = self._get_apps_with_licenses_concurrent(app_list)
            return packages

        except (subprocess.CalledProcessError, FileNotFoundError):
            return []

    def _get_apps_with_licenses_concurrent(self, app_list: List[Tuple[str, str, str]]) -> List[Dict[str, any]]:
        """Get app information with licenses using concurrent processing."""
        packages = []

        # Separate cached and uncached apps
        cached_apps = []
        uncached_apps = []

        for app_id, display_name, version in app_list:
            cached_licenses = self.cache.get("flatpak", app_id, version)
            if cached_licenses is not None:
                cached_apps.append({
                    "name": app_id,
                    "display_name": display_name,
                    "version": version,
                    "manager": "flatpak",
                    "licenses": cached_licenses
                })
            else:
                uncached_apps.append((app_id, display_name, version))

        packages.extend(cached_apps)

        # Process uncached apps concurrently
        if uncached_apps:
            max_workers = min(16, len(uncached_apps))  # Limit concurrent processes

            with ThreadPoolExecutor(max_workers=max_workers) as executor:
                # Submit all license fetch tasks
                future_to_app = {
                    executor.submit(self._get_flatpak_license_single, app_id, version): (app_id, display_name, version)
                    for app_id, display_name, version in uncached_apps
                }

                # Collect results as they complete
                for future in as_completed(future_to_app):
                    app_id, display_name, version = future_to_app[future]
                    try:
                        licenses = future.result()

                        # Cache the result
                        self.cache.set("flatpak", app_id, version, licenses)

                        packages.append({
                            "name": app_id,
                            "display_name": display_name,
                            "version": version,
                            "manager": "flatpak",
                            "licenses": licenses
                        })
                    except Exception as e:
                        # If license fetch fails, use inference
                        licenses = self._infer_flatpak_license(app_id)
                        packages.append({
                            "name": app_id,
                            "display_name": display_name,
                            "version": version,
                            "manager": "flatpak",
                            "licenses": licenses
                        })

        return packages

    def _get_flatpak_license_single(self, app_id: str, version: str) -> List[str]:
        """Get license information for a single Flatpak application."""
        try:
            # Try to get metadata which might contain license info
            result = subprocess.run(
                ["flatpak", "info", "--show-metadata", app_id],
                capture_output=True,
                text=True,
                check=True,
                timeout=10  # Add timeout to prevent hanging
            )

            # Look for license information in metadata
            licenses = []
            for line in result.stdout.split('\n'):
                if 'license' in line.lower():
                    # Extract license value
                    if '=' in line:
                        license_value = line.split('=', 1)[1].strip()
                        if license_value:
                            licenses.append(license_value)

            # If no license found in metadata, try to infer from app ID
            if not licenses:
                licenses = self._infer_flatpak_license(app_id)

            return licenses if licenses else ["unknown"]

        except (subprocess.CalledProcessError, FileNotFoundError, subprocess.TimeoutExpired):
            return self._infer_flatpak_license(app_id)

    @lru_cache(maxsize=1000)
    def _infer_flatpak_license(self, app_id: str) -> List[str]:
        """Infer license based on Flatpak app ID patterns (cached)."""
        # Check for known FOSS patterns
        for pattern, licenses in self._foss_patterns.items():
            if app_id.startswith(pattern):
                return licenses

        # Default to unknown for unrecognized patterns
        return ["unknown"]

    def _get_flatpak_license(self, app_id: str) -> List[str]:
        """Legacy method for backward compatibility."""
        return self._get_flatpak_license_single(app_id, "unknown")
